Here is the commit message:
KEYS: trusted: Fix a memory leak in tpm2_load_cmd

'tpm2_load_cmd' allocates a tempoary blob indirectly via 'tpm2_key_decode'
but it is not freed in the failure paths. Address this by wrapping the blob
into with a cleanup helper.

Cc: stable@vger.kernel.org # v5.13+
Fixes: f2219745250f ("security: keys: trusted: use ASN.1 TPM2 key format for the blobs")
Signed-off-by: Jarkko Sakkinen <jarkko@kernel.org>

Here is the root cause:
In `tpm2_load_cmd`, a temporary blob is allocated by `tpm2_key_decode` when the key is in new format, but the function fails to free that blob on all error paths (e.g., early returns from `tpm_buf_init`, `tpm2_key_decode` failures, or other `goto out` paths that bypass the conditional `kfree`). The existing cleanup only freed if `blob != payload->blob` at the end, but early exits before that point leak the memory.

Here is the patch:
  */
 static int tpm2_load_cmd(struct tpm_chip *chip,
 			 struct trusted_key_payload *payload,
 			 struct trusted_key_options *options,
 			 u32 *blob_handle)
 {
+	u8 *blob_ref __free(kfree) = NULL;
 	struct tpm_buf buf;
 	unsigned int private_len;
 	unsigned int public_len;
 	unsigned int blob_len;
 	u8 *blob, *pub;
 	int rc;
 	u32 attrs;

 	rc = tpm2_key_decode(payload, options, &blob);
 	if (rc) {
 		/* old form */
 		blob = payload->blob;
 		payload->old_format = 1;
+	} else {
+		/* Bind for cleanup: */
+		blob_ref = blob;
 	}

 	/* new format carries keyhandle but old format doesn't */
 	if (!options->keyhandle)
 		return -EINVAL;

 	/* must be big enough for at least the two be16 size counts */
 	if (payload->blob_len < 4)
 		return -EINVAL;

 	private_len = get_unaligned_be16(blob);

 	/* must be big enough for following public_len */
 	if (private_len + 2 + 2 > (payload->blob_len))
 		return -E2BIG;

 	public_len = get_unaligned_be16(blob + 2 + private_len);
 	if (private_len + 2 + public_len + 2 > payload->blob_len)
 		return -E2BIG;

 	pub = blob + 2 + private_len + 2;
 	/* key attributes are always at offset 4 */
 	attrs = get_unaligned_be32(pub + 4);

 	if ((attrs & (TPM2_OA_FIXED_TPM | TPM2_OA_FIXED_PARENT)) ==
 	    (TPM2_OA_FIXED_TPM | TPM2_OA_FIXED_PARENT))
 		payload->migratable = 0;
 	else
 		payload->migratable = 1;

 	blob_len = private_len + public_len + 4;
 	if (blob_len > payload->blob_len)
 		return -E2BIG;

 	rc = tpm2_start_auth_session(chip);
 	if (rc)
 		return rc;

 	rc = tpm_buf_init(&buf, TPM2_ST_SESSIONS, TPM2_CC_LOAD);
 	if (rc) {
 		tpm2_end_auth_session(chip);
 		return rc;
 	}

 	tpm_buf_append_name(chip, &buf, options->keyhandle, NULL);
 	tpm_buf_append_hmac_session(chip, &buf, 0, options->keyauth,
 				    TPM_DIGEST_SIZE);

 	tpm_buf_append(&buf, blob, blob_len);

 	if (buf.flags & TPM_BUF_OVERFLOW) {
 		rc = -E2BIG;
 		tpm2_end_auth_session(chip);
 		goto out;
 	}

 	tpm_buf_fill_hmac_session(chip, &buf);
 	rc = tpm_transmit_cmd(chip, &buf, 4, "loading blob");
 	rc = tpm_buf_check_hmac_response(chip, &buf, rc);
 	if (!rc)
 		*blob_handle = be32_to_cpup(
 			(__be32 *) &buf.data[TPM_HEADER_SIZE]);

 out:
-	if (blob != payload->blob)
-		kfree(blob);
 	tpm_buf_destroy(&buf);

 	if (rc > 0)
 		rc = -EPERM;

 	return rc;
 }



